function makeProject(qty,length){sources=Array.from({length:qty},(_,i)=>({id:i+1,length}));beams=sources.map((s,i)=>({id:nextId++,source:s.id,name:`Batang ${sourceCode(s.id)}`,pieceNo:1,length:s.length,x:50+s.length/2,y:65+i*58,angle:0,kind:'whole',generation:0,locks:[]}));selectedId=null;cutHistory=[];undoStack=[];redoStack=[];measureMode=false;measureDraft=null;constructionPoints=[];nextPointId=1;boltJoints=[];nextBoltId=1;hideTool();view={x:0,y:0,w:700,h:Math.max(520,qty*58+80)};save();renderAll();$('projectModal').classList.add('hidden');showToast(`${qty} batang berhasil dibuat`)}
$('projectForm').addEventListener('submit',e=>{e.preventDefault();const q=Math.min(30,Math.max(1,Math.round(n('startQty',4)))),l=n('startLength',600);if(!l)return;nextId=1;makeProject(q,l)});
$('newProject').onclick=()=>{$('projectModal').classList.remove('hidden')};
function addMaterials(qty,length){if(!beams.length){nextId=1;makeProject(qty,length);return}pushHistory();const firstSource=Math.max(0,...sources.map(s=>s.id))+1,maxBottom=Math.max(...beams.map(b=>beamBounds(b).bottom)),left=Math.min(...beams.map(b=>beamBounds(b).left)),baseY=maxBottom+55;for(let i=0;i<qty;i++){const source={id:firstSource+i,length};sources.push(source);beams.push({id:nextId++,source:source.id,name:`Batang ${sourceCode(source.id)}`,pieceNo:1,length,x:left+length/2,y:baseY+i*58,angle:0,kind:'whole',generation:0,locks:[]})}selectedId=beams[beams.length-qty].id;hideTool();save();renderAll();fitView();showToast(`${qty} bahan baru ditambahkan`)}
$('addMaterial').onclick=()=>{$('materialModal').classList.remove('hidden');$('materialQty').focus()};
$('cancelMaterial').onclick=()=>$('materialModal').classList.add('hidden');
$('materialForm').addEventListener('submit',e=>{e.preventDefault();const remaining=Math.max(0,200-sources.length),q=Math.min(30,remaining,Math.max(1,Math.round(n('materialQty',1)))),length=n('materialLength',600);if(!remaining){showToast('Batas 200 bahan per proyek');return}if(!length)return;addMaterials(q,length);$('materialModal').classList.add('hidden')});

function renderCanvas(){objects.innerHTML='';beams.forEach(b=>{const g=document.createElementNS(NS,'g');g.classList.add('beam');if(b.id===selectedId)g.classList.add('selected');g.dataset.id=b.id;g.setAttribute('transform',`translate(${b.x} ${b.y}) rotate(${-b.angle})`);g.innerHTML=`<rect class="beam-hit" x="${-b.length/2-8}" y="-22" width="${b.length+16}" height="44"/><rect class="beam-body" x="${-b.length/2}" y="${-PROFILE_H/2}" width="${b.length}" height="${PROFILE_H}" fill="url(#steelProfile)"/><rect class="beam-edge" x="${-b.length/2}" y="${-PROFILE_H/2}" width="${b.length}" height="${PROFILE_H}"/><line class="beam-groove" x1="${-b.length/2+2}" y1="-2.55" x2="${b.length/2-2}" y2="-2.55"/><line class="beam-groove lower" x1="${-b.length/2+2}" y1="2.55" x2="${b.length/2-2}" y2="2.55"/><text class="beam-label" x="0" y="0">${pieceCode(b)}: ${fmt(b.length)} cm</text>`;objects.appendChild(g)});renderJoints();canvas.setAttribute('viewBox',`${view.x} ${view.y} ${view.w} ${view.h}`);$('canvasEmpty').style.display=beams.length?'none':'grid'}
function renderSelection(){const b=selected(),card=$('selectionCard');card.classList.toggle('disabled',!b);$('undoCut').disabled=!cutHistory.length;if(!b){$('selectedTitle').textContent='Belum ada objek';['infoLength','infoAngle','infoSource','infoStatus'].forEach(id=>$(id).textContent='—');return}$('selectedTitle').textContent=pieceCode(b);$('infoLength').textContent=fmt(b.length)+' cm';$('infoAngle').textContent=fmt(normalAngle(b.angle))+'°';$('infoSource').textContent='Bahan '+sourceCode(b.source);$('infoStatus').textContent=b.kind==='whole'?'Utuh':b.kind==='cut'?'Potong':'Sisa';$('angleInput').value=normalAngle(b.angle);updateCutPreview()}
function renderInventory(){if(!sources.length){$('inventory').innerHTML='<p class="empty-list">Belum ada bahan.</p>';return}$('totalStock').textContent=sources.length;$('inventory').innerHTML=sources.map(s=>{const pieces=beams.filter(b=>b.source===s.id).sort((a,b)=>(a.pieceNo||1)-(b.pieceNo||1));return `<div class="source"><div class="source-head"><b>Batang ${sourceCode(s.id)}</b><span>Awal ${fmt(s.length)} cm • ${pieces.length} objek</span></div><div class="piece-list">${pieces.map(b=>`<button class="piece-chip ${b.id===selectedId?'active':''}" data-select="${b.id}"><b>${pieceCode(b)} • ${fmt(b.length)} cm</b>${b.kind==='whole'?'Utuh':b.kind==='cut'?'Potongan':'Sisa'} • ${fmt(normalAngle(b.angle))}°${b.locks?.length?' • 🔒'+b.locks.length:''}</button>`).join('')}</div></div>`}).join('');document.querySelectorAll('[data-select]').forEach(x=>x.onclick=()=>selectBeam(+x.dataset.select))}
function historyState(){return JSON.stringify({beams,sources,selectedId,nextId,constructionPoints,nextPointId,boltJoints,nextBoltId})}
function pushHistory(raw=historyState()){if(undoStack[undoStack.length-1]!==raw)undoStack.push(raw);if(undoStack.length>60)undoStack.shift();redoStack=[]}
function normalizeBeams(list){list.forEach(b=>{if(!Array.isArray(b.locks)){b.locks=[];if(b.lock){if(b.lock.selfT===undefined)b.lock.selfT=b.lock.selfEnd==='start'?0:1;b.locks.push(b.lock)}}delete b.lock});return list}
function restoreHistory(raw){const s=JSON.parse(raw);beams=normalizeBeams(s.beams);sources=s.sources;selectedId=s.selectedId;nextId=s.nextId;constructionPoints=s.constructionPoints||[];nextPointId=s.nextPointId||1;boltJoints=s.boltJoints||[];nextBoltId=s.nextBoltId||Math.max(0,...boltJoints.map(x=>x.id))+1;activeJointKey=null;measureDraft=null;hideTool();renderAll();save()}
