function renderMeasureGuide(){if(!measureDraft){guides.innerHTML='';return}const source=beams.find(b=>b.id===measureDraft.sourceId);if(!source){measureDraft=null;guides.innerHTML='';return}const a=pointOnBeam(source,measureDraft.sourceT);if(measureDraft.angle===null){guides.innerHTML=`<circle class="measure-end" cx="${a.x}" cy="${a.y}" r="6"/>`;return}const distance=Math.max(.1,parseFloat($('measureDistance').value)||100),v=vector(measureDraft.angle),b={x:a.x+v.x*distance,y:a.y+v.y*distance},mx=(a.x+b.x)/2,my=(a.y+b.y)/2,label=`${fmt(distance)} cm • ${fmt(measureDraft.angle)}°`,w=Math.max(92,label.length*6.2);guides.innerHTML=`<line class="measure-line" x1="${a.x}" y1="${a.y}" x2="${b.x}" y2="${b.y}"/><circle class="measure-end" cx="${a.x}" cy="${a.y}" r="5"/><circle class="measure-end" cx="${b.x}" cy="${b.y}" r="5"/><rect class="measure-label-bg" x="${mx-w/2}" y="${my-11}" width="${w}" height="22" rx="7"/><text class="measure-label" x="${mx}" y="${my}">${label}</text>`}
function renderAll(){renderCanvas();renderSelection();renderInventory();updateZoomLabel();$('undoAction').disabled=!undoStack.length;$('redoAction').disabled=!redoStack.length;$('measureTool').classList.toggle('active',measureMode);document.querySelector('.canvas-actions').classList.toggle('has-selection',!!selected());$('canvasUndoCut').disabled=!findMergeCandidate(selected());const fixed=!!selected()?.moveLocked;$('canvasMoveLock').classList.toggle('active',fixed);$('canvasMoveLock').title=fixed?'Buka kunci posisi objek':'Kunci posisi objek';if(measureMode)renderMeasureGuide();else guides.innerHTML=''}
$('undoAction').onclick=undoAction;$('redoAction').onclick=redoAction;
$('magicTool').onclick=openMagic;$('cancelMagic').onclick=()=>{$('magicModal').classList.add('hidden');magicPlan=null};$('applyMagic').onclick=()=>{if(magicPlan)applyMagicLayout(magicPlan)};$('magicBaseSelect').onchange=refreshMagic;['magicMirrorPosition','magicMatchAngle','magicCenterObjects','magicEqualSpacing'].forEach(id=>$(id).onchange=()=>{if(magicPlan)renderMagicPlan(magicPlan)});
