canvas.addEventListener('pointerdown',e=>{e.preventDefault();const joint=e.target.closest('[data-joint-action]');if(joint){handleJointAction(joint,e);return}const directionPoint=screenPoint(e);if(measureMode&&measureDraft&&measureDraft.angle===null){const start=pointOnBeam(beams.find(b=>b.id===measureDraft.sourceId),measureDraft.sourceT),dx=directionPoint.x-start.x,dy=directionPoint.y-start.y;if(Math.hypot(dx,dy)>2){measureDraft.angle=normalAngle(-Math.atan2(dy,dx)*180/Math.PI);showTool('measureInputTool');renderAll();showToast('Masukkan jarak atau tarik ujung meteran')}return}canvas.setPointerCapture(e.pointerId);pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});if(pointers.size===2){beginPinch();return}const g=e.target.closest('.beam'),p=directionPoint;if(g){const id=+g.dataset.id,b=beams.find(x=>x.id===id);selectedId=id;activeJointKey=null;drag={type:'beam',id,dx:p.x-b.x,dy:p.y-b.y,grabT:projectPoint(p,b).t,before:historyState(),snapLock:null,lockAnchors:beamLockAnchors(b)};renderAll()}else{selectedId=null;activeJointKey=null;if(!measureMode)hideTool();drag={type:'pan',sx:e.clientX,sy:e.clientY,start:{...view}};renderAll()}});
canvas.addEventListener('pointermove',e=>{if(!pointers.has(e.pointerId))return;pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});if(pointers.size>=2){updatePinch();return}if(!drag)return;if(drag.type==='beam'){const b=beams.find(x=>x.id===drag.id),p=screenPoint(e),anchors=drag.lockAnchors||[];if(anchors.length>=2){drawGuides({x:b.x,y:b.y,gx:false,gy:false,joint:anchors[0].point},b)}else if(anchors.length===1){rotateBeamAroundAnchor(b,p,drag.grabT,anchors[0]);drawGuides({x:b.x,y:b.y,gx:false,gy:false,joint:anchors[0].point},b)}else{const raw={x:p.x-drag.dx,y:p.y-drag.dy},snap=snapPosition(b,raw);b.x=snap.x;b.y=snap.y;drag.snapLock=snap.snapLock||null;drawGuides(snap,b)}renderCanvas()}else if(drag.type==='measure'){const source=beams.find(b=>b.id===measureDraft?.sourceId);if(!source)return;const start=pointOnBeam(source,measureDraft.sourceT),p=screenPoint(e),dx=p.x-start.x,dy=p.y-start.y,distance=Math.max(.1,Math.hypot(dx,dy));measureDraft.angle=normalAngle(-Math.atan2(dy,dx)*180/Math.PI);$('measureDistance').value=Math.round(distance*10)/10;$('measureAngle').value=measureDraft.angle;if(measureDraft.editingPointId){const cp=constructionPoints.find(x=>x.id===measureDraft.editingPointId);if(cp){cp.relativeAngle=normalAngle(measureDraft.angle-source.angle);cp.distance=distance;applyLocks(source.id)}}renderCanvas();renderMeasureGuide()}else{const r=canvas.getBoundingClientRect(),dx=(e.clientX-drag.sx)*drag.start.w/r.width,dy=(e.clientY-drag.sy)*drag.start.h/r.height;view.x=drag.start.x-dx;view.y=drag.start.y-dy;renderCanvas()}});
function finishPointer(e){pointers.delete(e.pointerId);if(pointers.size<2)gesture=null;if(!pointers.size){const action=drag,before=action&&action.before,moved=!!(action&&before&&action.type==='beam'&&before!==historyState()),pointMoved=!!(action&&before&&action.type==='measure'&&action.editingPointId&&before!==historyState());if(moved||pointMoved)pushHistory(before);if(moved&&action.snapLock){const b=beams.find(x=>x.id===action.id),lock=action.snapLock;if(b&&lock.pointId&&!(b.locks||[]).some(x=>x.pointId===lock.pointId)){b.locks.push({selfT:lock.selfT,pointId:lock.pointId});showToast('Ujung terkunci ke titik meteran')}else if(b&&lock.boltId&&!(b.locks||[]).some(x=>x.boltId===lock.boltId)){b.locks.push({selfT:lock.selfT,boltId:lock.boltId});positionLocked(b);showToast('Ujung bergabung ke pusat baut')}}drag=null;guides.innerHTML='';renderAll();if(moved||pointMoved)save()}}
canvas.addEventListener('pointerup',finishPointer);canvas.addEventListener('pointercancel',finishPointer);
canvas.addEventListener('wheel',e=>{e.preventDefault();const p=screenPoint(e);zoomAt(e.deltaY<0?.88:1.14,p.x,p.y)},{passive:false});
function screenPoint(e){return clientToWorld(e.clientX,e.clientY)}
function clientToWorld(cx,cy,v=view){const r=canvas.getBoundingClientRect();return{x:v.x+(cx-r.left)*v.w/r.width,y:v.y+(cy-r.top)*v.h/r.height}}
function beginPinch(){const p=[...pointers.values()],mid={x:(p[0].x+p[1].x)/2,y:(p[0].y+p[1].y)/2};gesture={distance:Math.hypot(p[1].x-p[0].x,p[1].y-p[0].y),start:{...view},anchor:clientToWorld(mid.x,mid.y),mid};drag=null;guides.innerHTML=''}
function updatePinch(){if(!gesture)beginPinch();const p=[...pointers.values()],dist=Math.max(20,Math.hypot(p[1].x-p[0].x,p[1].y-p[0].y)),mid={x:(p[0].x+p[1].x)/2,y:(p[0].y+p[1].y)/2},nw=Math.max(180,Math.min(1800,gesture.start.w*gesture.distance/dist)),nh=nw*(gesture.start.h/gesture.start.w),r=canvas.getBoundingClientRect();view={x:gesture.anchor.x-(mid.x-r.left)*nw/r.width,y:gesture.anchor.y-(mid.y-r.top)*nh/r.height,w:nw,h:nh};renderCanvas();updateZoomLabel()}
function snapPosition(b,p){const result={x:p.x,y:p.y,gx:false,gy:false,joint:null,snapLock:null};if(!snapEnabled)return result;const r=canvas.getBoundingClientRect(),threshold=7*view.w/Math.max(1,r.width),v=vector(b.angle),moving=[{x:p.x-v.x*b.length/2,y:p.y-v.y*b.length/2,selfT:0},{x:p.x+v.x*b.length/2,y:p.y+v.y*b.length/2,selfT:1}],targets=[];beams.filter(x=>x.id!==b.id).forEach(o=>{const e=ends(o);targets.push(e.start,e.end)});constructionPoints.forEach(cp=>{const q=constructionWorld(cp);if(q&&cp.sourceId!==b.id&&!createsLockCycle(cp.sourceId,b.id))targets.push({...q,pointId:cp.id})});boltJoints.forEach(bolt=>targets.push({x:bolt.x,y:bolt.y,boltId:bolt.id}));let best=threshold;moving.forEach(me=>targets.forEach(t=>{const d=Math.hypot(me.x-t.x,me.y-t.y);if(d<best){best=d;result.x=p.x+t.x-me.x;result.y=p.y+t.y-me.y;result.joint=t;result.snapLock=t.pointId?{pointId:t.pointId,selfT:me.selfT}:t.boltId?{boltId:t.boltId,selfT:me.selfT}:null}}));const cx=view.x+view.w/2,cy=view.y+view.h/2;if(result.joint){if(Math.abs(result.x-cx)<threshold)result.gx='TENGAH';if(Math.abs(result.y-cy)<threshold)result.gy='TENGAH';return result}if(Math.abs(p.x-cx)<threshold){result.x=cx;result.gx='TENGAH'}if(Math.abs(p.y-cy)<threshold){result.y=cy;result.gy='TENGAH'}return result}
function beamBounds(b){const r=b.angle*Math.PI/180,c=Math.abs(Math.cos(r)),s=Math.abs(Math.sin(r)),hw=(b.length*c+PROFILE_H*s)/2,hh=(b.length*s+PROFILE_H*c)/2;return{left:b.x-hw,right:b.x+hw,top:b.y-hh,bottom:b.y+hh,cx:b.x,cy:b.y}}
function closestBeamPair(a,b){const ea=ends(a),eb=ends(b),candidates=[];function fromA(p){const q=projectPoint(p,b);candidates.push({p1:p,p2:{x:q.x,y:q.y},distance:q.distance})}function fromB(p){const q=projectPoint(p,a);candidates.push({p1:{x:q.x,y:q.y},p2:p,distance:q.distance})}fromA(ea.start);fromA(ea.end);fromB(eb.start);fromB(eb.end);const crossing=segmentIntersection(a,b);if(crossing)candidates.push({p1:{x:crossing.x,y:crossing.y},p2:{x:crossing.x,y:crossing.y},distance:0});return candidates.sort((x,y)=>x.distance-y.distance)[0]}
function physicalBeamGap(a,b){return Math.max(0,closestBeamPair(a,b).distance-PROFILE_H)}
function renderSmartReference(b,target){objects.querySelectorAll('.smart-reference').forEach(x=>x.classList.remove('smart-reference'));const group=objects.querySelector(`[data-id="${target.id}"]`);if(group)group.classList.add('smart-reference');const pair=closestBeamPair(b,target),gap=physicalBeamGap(b,target),mx=(pair.p1.x+pair.p2.x)/2,my=(pair.p1.y+pair.p2.y)/2,label=`ACUAN ${pieceCode(target)} • ${fmt(gap)} cm`,w=Math.max(92,label.length*5.2);guides.innerHTML=`<line class="smart-guide" x1="${pair.p1.x}" y1="${pair.p1.y}" x2="${pair.p2.x}" y2="${pair.p2.y}"/><circle class="smart-guide-point" cx="${pair.p1.x}" cy="${pair.p1.y}" r="3"/><circle class="smart-guide-point" cx="${pair.p2.x}" cy="${pair.p2.y}" r="3"/><rect class="smart-guide-label-bg" x="${mx-w/2}" y="${my-18}" width="${w}" height="16" rx="5"/><text class="smart-guide-label" x="${mx}" y="${my-10}">${label}</text>`}
function allSmartTargets(b){return beams.filter(x=>x.id!==b.id).map(beam=>({beam,gap:physicalBeamGap(b,beam),rank:closestBeamPair(b,beam).distance})).sort((a,c)=>a.rank-c.rank||Math.hypot(a.beam.x-b.x,a.beam.y-b.y)-Math.hypot(c.beam.x-b.x,c.beam.y-b.y))}
