function chooseSmartTarget(id,manual=false){const b=beams.find(x=>x.id===smartSourceId)||selected(),target=beams.find(x=>x.id===+id&&x.id!==b?.id);if(!b||!target){$('smartReference').textContent='Objek acuan tidak tersedia';return}smartTargetId=target.id;smartTargetManual=manual;smartPickReference=false;$('smartPickReference').classList.remove('active');$('smartPickReference').textContent='Pilih di kanvas';$('smartTargetSelect').value=String(target.id);document.querySelectorAll('[data-smart-dir]').forEach(btn=>btn.classList.remove('active'));const gap=physicalBeamGap(b,target);$('smartDistance').value=Math.round(gap*10)/10;$('smartReference').textContent=`${manual?'Acuan pilihan':'Acuan terdekat'}: ${pieceCode(target)} • jarak nyata ${fmt(gap)} cm`;renderSmartReference(b,target)}
