function measureMarkup(d){if(!d)return'';if(d.x1!==undefined){const mid=(d.x1+d.x2)/2,w=Math.max(38,String(fmt(d.gap)).length*7+20);return `<line class="distance-line" x1="${d.x1}" y1="${d.y}" x2="${d.x2}" y2="${d.y}"/><line class="distance-tick" x1="${d.x1}" y1="${d.y-7}" x2="${d.x1}" y2="${d.y+7}"/><line class="distance-tick" x1="${d.x2}" y1="${d.y-7}" x2="${d.x2}" y2="${d.y+7}"/><rect class="distance-bg" x="${mid-w/2}" y="${d.y-18}" width="${w}" height="15" rx="5"/><text class="distance-text" x="${mid}" y="${d.y-7}">${fmt(d.gap)} cm</text>`}const mid=(d.y1+d.y2)/2,w=Math.max(38,String(fmt(d.gap)).length*7+20);return `<line class="distance-line" x1="${d.x}" y1="${d.y1}" x2="${d.x}" y2="${d.y2}"/><line class="distance-tick" x1="${d.x-7}" y1="${d.y1}" x2="${d.x+7}" y2="${d.y1}"/><line class="distance-tick" x1="${d.x-7}" y1="${d.y2}" x2="${d.x+7}" y2="${d.y2}"/><rect class="distance-bg" x="${d.x+5}" y="${mid-8}" width="${w}" height="15" rx="5"/><text class="distance-text" x="${d.x+5+w/2}" y="${mid+3}">${fmt(d.gap)} cm</text>`}
