function normalAngle(a){a=((a%360)+360)%360;return Math.round(a*10)/10}
function getLockPoint(lock){if(lock.boltId){const bolt=boltJoints.find(x=>x.id===lock.boltId);return bolt?{x:bolt.x,y:bolt.y}:null}if(lock.pointId){const cp=constructionPoints.find(x=>x.id===lock.pointId);return cp?constructionWorld(cp):null}const target=beams.find(x=>x.id===lock.targetId);if(!target)return null;return pointOnBeam(target,lock.targetT)}
