function buildPrintReport(){const totalLength=sources.reduce((sum,s)=>sum+s.length,0),remainders=beams.filter(b=>b.kind==='remainder'),restLength=remainders.reduce((sum,b)=>sum+b.length,0),stockRows=sources.map(s=>{const pieces=beams.filter(b=>b.source===s.id).sort((a,b)=>(a.pieceNo||1)-(b.pieceNo||1)),rest=pieces.filter(b=>b.kind==='remainder').reduce((n,b)=>n+b.length,0);return`<div><b>${sourceCode(s.id)} • ${fmt(s.length)} cm</b><span>${pieces.map(b=>`${pieceCode(b)} ${fmt(b.length)}${b.kind==='remainder'?' sisa':''}`).join(' + ')}</span><strong>Sisa ${fmt(rest)} cm</strong></div>`}).join(''),stamp=new Date().toLocaleString('id-ID');$('printReport').innerHTML=`<section class="print-page"><div class="print-head"><div><h1>Rencana Kuda-kuda 2D</h1><p>Ukuran objek dalam sentimeter</p></div><aside>${stamp}<br>A4 landscape • 1 halaman</aside></div><div class="print-summary"><div><b>${sources.length}</b><span>Batang awal</span></div><div><b>${fmt(totalLength)} cm</b><span>Total bahan</span></div><div><b>${fmt(restLength)} cm</b><span>Total sisa</span></div></div><div class="print-drawing">${reportSvg()}</div><div class="print-stock-title">Rincian bahan dan potongan</div><div class="print-stock-grid">${stockRows}</div><p class="print-note">Kode dan panjang ditempatkan di dalam masing-masing objek. Empat bulatan kecil menunjukkan sambungan skrup.</p></section>`}
