function validNumber(v){return Number.isFinite(Number(v))}
function importProjectData(data){const s=data&&data.state?data.state:data;if(data?.format&&data.format!=='aplikasi-meteran-project')throw new Error('Format file tidak dikenali');if(!s||!Array.isArray(s.beams)||!Array.isArray(s.sources)||s.sources.length>200||s.beams.length>5000)throw new Error('Data proyek tidak valid');const sourceIds=new Set();s.sources.forEach(x=>{if(!validNumber(x.id)||!validNumber(x.length)||Number(x.length)<=0||sourceIds.has(Number(x.id)))throw new Error('Data bahan tidak valid');x.id=Number(x.id);x.length=Number(x.length);sourceIds.add(x.id)});const beamIds=new Set();s.beams.forEach(b=>{if(!validNumber(b.id)||!sourceIds.has(Number(b.source))||!validNumber(b.length)||Number(b.length)<=0||!validNumber(b.x)||!validNumber(b.y)||!validNumber(b.angle)||beamIds.has(Number(b.id)))throw new Error('Data objek tidak valid');b.id=Number(b.id);b.source=Number(b.source);b.length=Number(b.length);b.x=Number(b.x);b.y=Number(b.y);b.angle=Number(b.angle);beamIds.add(b.id)});beams=normalizeBeams(s.beams);sources=s.sources;nextId=validNumber(s.nextId)?Number(s.nextId):Math.max(0,...beams.map(b=>b.id))+1;view=s.view&&['x','y','w','h'].every(k=>validNumber(s.view[k]))?s.view:{x:0,y:0,w:700,h:520};cutHistory=Array.isArray(s.cutHistory)?s.cutHistory:[];constructionPoints=Array.isArray(s.constructionPoints)?s.constructionPoints:[];nextPointId=validNumber(s.nextPointId)?Number(s.nextPointId):Math.max(0,...constructionPoints.map(p=>Number(p.id)||0))+1;boltJoints=Array.isArray(s.boltJoints)?s.boltJoints.filter(x=>validNumber(x.id)&&validNumber(x.x)&&validNumber(x.y)).map(x=>({id:Number(x.id),x:Number(x.x),y:Number(x.y)})):[];nextBoltId=validNumber(s.nextBoltId)?Number(s.nextBoltId):Math.max(0,...boltJoints.map(x=>x.id))+1;selectedId=beamIds.has(Number(s.selectedId))?Number(s.selectedId):null;snapEnabled=s.snapEnabled!==false;undoStack=Array.isArray(s.undoStack)?s.undoStack.slice(-60):[];redoStack=Array.isArray(s.redoStack)?s.redoStack.slice(-60):[];measureMode=false;measureDraft=null;activeJointKey=null;hideTool();$('projectModal').classList.add('hidden');$('materialModal').classList.add('hidden');$('snapToggle').classList.toggle('on',snapEnabled);$('snapToggle').textContent=snapEnabled?'Magnet':'Bebas';save();renderAll();showToast(`Proyek dimuat • ${sources.length} bahan`)}
function importProjectText(text){try{importProjectData(JSON.parse(text))}catch(e){showToast(e.message||'File proyek gagal dibaca')}}
function importProjectFromBase64(encoded){try{const bytes=Uint8Array.from(atob(encoded),c=>c.charCodeAt(0)),text=new TextDecoder().decode(bytes);importProjectText(text)}catch(e){showToast('File proyek gagal dibaca')}}
function openProjectFile(){if(window.AndroidProject&&AndroidProject.openProject){AndroidProject.openProject();return}$('projectFileInput').click()}
$('saveProject').onclick=exportProject;$('importProject').onclick=openProjectFile;$('importFromStart').onclick=openProjectFile;
$('projectFileInput').onchange=e=>{const file=e.target.files[0];if(!file)return;const reader=new FileReader();reader.onload=()=>importProjectText(reader.result);reader.onerror=()=>showToast('File proyek gagal dibaca');reader.readAsText(file);e.target.value=''};
function save(){localStorage.setItem('kudakuda2d',JSON.stringify(projectState()))}
function load(){try{const d=JSON.parse(localStorage.getItem('kudakuda2d'));if(d&&d.beams&&d.sources){beams=normalizeBeams(d.beams);sources=d.sources;sources.forEach(s=>beams.filter(b=>b.source===s.id).sort((a,b)=>a.id-b.id).forEach((b,i)=>{if(!b.pieceNo)b.pieceNo=i+1}));nextId=d.nextId||Math.max(0,...beams.map(b=>b.id))+1;view=d.view||view;cutHistory=d.cutHistory||[];constructionPoints=d.constructionPoints||[];nextPointId=d.nextPointId||Math.max(0,...constructionPoints.map(p=>p.id))+1;boltJoints=Array.isArray(d.boltJoints)?d.boltJoints:[];nextBoltId=d.nextBoltId||Math.max(0,...boltJoints.map(x=>x.id))+1;selectedId=beams.some(b=>b.id===d.selectedId)?d.selectedId:null;snapEnabled=d.snapEnabled!==false;undoStack=Array.isArray(d.undoStack)?d.undoStack.slice(-60):[];redoStack=Array.isArray(d.redoStack)?d.redoStack.slice(-60):[];$('snapToggle').classList.toggle('on',snapEnabled);$('snapToggle').textContent=snapEnabled?'Magnet':'Bebas';$('projectModal').classList.add('hidden')}}catch(e){}renderAll()}
function compactMeterMarkers(){joints.querySelectorAll('.measure-point circle').forEach(x=>x.setAttribute('r','3.5'));joints.querySelectorAll('.measure-point text').forEach(x=>x.setAttribute('font-size','4'));joints.querySelectorAll('.construction-point .target-ring').forEach(x=>x.setAttribute('r','3.5'));joints.querySelectorAll('.construction-point .target-cross').forEach(x=>x.setAttribute('d','M-2.2 0H2.2M0-2.2V2.2'));joints.querySelectorAll('.construction-label').forEach(x=>{x.setAttribute('y','-7');x.setAttribute('font-size','5')});joints.querySelectorAll('.measure-drag-point').forEach(x=>x.innerHTML='<circle class="measure-drag-hit" r="13"/><circle class="measure-drag-mark" r="3.75"/><text x="0" y=".3">×</text>')}
const renderJointsBase=renderJoints;renderJoints=function(){renderJointsBase();compactMeterMarkers()};
const baseCutAction=$('cutButton').onclick;$('cutButton').onclick=()=>{const active=selected();if(active?.moveLocked){showToast('Buka Kunci Posisi untuk memotong');return}const known=new Set(beams.map(b=>b.id)),previousMate=active?.cutMateId;baseCutAction();const current=active&&beams.find(b=>b.id===active.id),fresh=beams.find(b=>!known.has(b.id)&&current&&b.source===current.source);if(current&&fresh){const oldMate=beams.find(b=>b.id===previousMate);if(oldMate&&oldMate.cutMateId===current.id)delete oldMate.cutMateId;current.cutMateId=fresh.id;fresh.cutMateId=current.id;current.cutRole='cut';fresh.cutRole='rest';save()}};
canvas.addEventListener('pointerdown',e=>{const g=e.target.closest('.beam');if(smartPickReference&&g){e.preventDefault();e.stopImmediatePropagation();const id=+g.dataset.id;if(id===smartSourceId){showToast('Pilih objek lain sebagai acuan');return}chooseSmartTarget(id,true);showToast(`${pieceCode(beams.find(x=>x.id===id))} dipilih sebagai acuan`);return}if(e.target.closest('[data-joint-action]'))return;const b=g&&beams.find(x=>x.id===+g.dataset.id);if(!b?.moveLocked)return;e.preventDefault();e.stopImmediatePropagation();selectedId=b.id;activeJointKey=null;hideTool();renderAll();showToast('Objek terkunci • gunakan tombol Kunci Posisi untuk membuka')},true);
load();
